# -*- coding: utf-8 -*-
OT_DAYS_3 = [
{"day":39,"book":"Joshua","ref":"Joshua 1-5","title":"Crossing Over in Courage",
 "chapters":[
  ("Josh 1","God commissions Joshua to lead Israel into Canaan, repeatedly urging him to 'be strong and courageous' since God's presence goes with him."),
  ("Josh 2","Rahab, a Canaanite prostitute in Jericho, hides Israel's spies and professes faith in Israel's God, securing her family's safety."),
  ("Josh 3","Israel crosses the Jordan River on dry ground as the priests carry the Ark, echoing the earlier Red Sea crossing."),
  ("Josh 4","Twelve memorial stones are set up from the Jordan riverbed as a lasting reminder for future generations of God's miraculous provision."),
  ("Josh 5","Israel renews circumcision and celebrates Passover in the land, and Joshua encounters the mysterious 'commander of the LORD's army' before Jericho."),
 ],
 "themes":["Courage for God's calling is grounded in His promised presence, not personal confidence.","God preserves memorials of His faithfulness so future generations won't forget."],
 "expositor":("davis","Dale Ralph Davis observed that God's repeated command to Joshua to 'be strong and courageous' was never a call to manufacture confidence, but to act boldly because of a specific, repeated promise: 'the LORD your God will be with you wherever you go.'"),
 "reflect":"What situation calls for courage right now that could be grounded in God's promised presence rather than your own confidence level?"},

{"day":40,"book":"Joshua","ref":"Joshua 6-10","title":"Jericho Falls, Sin Is Exposed",
 "chapters":[
  ("Josh 6","Jericho's walls fall after Israel's obedient, unconventional march around the city for seven days."),
  ("Josh 7","Achan's hidden sin -- taking devoted items from Jericho -- causes Israel's defeat at Ai until the sin is confronted and removed."),
  ("Josh 8","Israel conquers Ai after dealing with Achan's sin, and Joshua renews the covenant at Mount Ebal."),
  ("Josh 9","The Gibeonites deceive Israel into a peace treaty through trickery, and Israel is bound to honor it despite being misled."),
  ("Josh 10","Joshua defeats a coalition of Amorite kings in a decisive battle, aided by God's remarkable intervention -- the sun standing still."),
 ],
 "themes":["Obedience to God's unconventional instructions can look strange yet still be the path to victory.","Hidden sin within a community can have consequences reaching far beyond the individual."],
 "expositor":("kaiser","Kaiser noted that Achan's sin in Joshua 7 -- taking devoted items for himself -- shows that private disobedience within a covenant community is never purely private in its consequences."),
 "reflect":"Is there a private compromise you've assumed only affects you, that might actually be impacting others around you?"},

{"day":41,"book":"Joshua","ref":"Joshua 11-15","title":"Complete Victory, A Faithful Old Man's Request",
 "chapters":[
  ("Josh 11","Joshua defeats the northern coalition of Canaanite kings, completing the major military campaigns."),
  ("Josh 12","A summary list catalogs all the kings Israel defeated on both sides of the Jordan."),
  ("Josh 13","The land east of the Jordan is allotted to Reuben, Gad, and half of Manasseh."),
  ("Josh 14","Caleb, now 85, requests and receives the hill country he was promised decades earlier for his faithful, wholehearted trust at Kadesh Barnea."),
  ("Josh 15","The territory allotted to the tribe of Judah is described in detail, foreshadowing its future prominence."),
 ],
 "themes":["Faithful, wholehearted trust in God can be rewarded even decades later.","God's promises of land were fulfilled in specific, real, allotted detail."],
 "expositor":("davis","Dale Ralph Davis pointed out that Caleb's request for the hill country at age 85 -- 'give me this mountain' -- models a faith that doesn't fade with age but grows bolder with decades of proven experience of God's faithfulness."),
 "reflect":"What would 'asking for the mountain' -- a bold request rooted in decades of trusting God -- look like for you at this stage of life?"},

{"day":42,"book":"Joshua","ref":"Joshua 16-20","title":"Dividing the Land, Providing Refuge",
 "chapters":[
  ("Josh 16","The territory allotted to Ephraim is described, alongside the incomplete conquest of Canaanite inhabitants in Gezer."),
  ("Josh 17","The territory allotted to Manasseh is described, including Zelophehad's daughters' fulfilled inheritance."),
  ("Josh 18","The remaining seven tribes' territories are surveyed and allotted by casting lots before the LORD at Shiloh."),
  ("Josh 19","The territories of Simeon, Zebulun, Issachar, Asher, Naphtali, and Dan are allotted, completing the land division."),
  ("Josh 20","Six cities of refuge are designated for the protection of those guilty of accidental manslaughter."),
 ],
 "themes":["Incomplete obedience in fully driving out the Canaanites planted seeds for later compromise.","Cities of refuge show God's justice included mercy and due process, not merely punishment."],
 "expositor":("kaiser","Kaiser observed that the recurring note of incomplete conquest in Joshua 16-17 quietly foreshadows the compromises and idolatry that will plague Israel throughout the book of Judges that follows."),
 "reflect":"Is there an area of 'incomplete conquest' in your own life -- something partially, but not fully, dealt with -- that risks growing back?"},

{"day":43,"book":"Joshua","ref":"Joshua 21-24","title":"As for Me and My Household",
 "chapters":[
  ("Josh 21","Levitical cities are allotted throughout the tribal territories, fulfilling God's provision for the priestly tribe."),
  ("Josh 22","The eastern tribes build an altar that nearly sparks civil war until its true, non-idolatrous purpose is clarified."),
  ("Josh 23","Joshua's farewell address urges Israel to remain faithful and avoid entanglement with the remaining Canaanite nations."),
  ("Josh 24","Joshua renews the covenant at Shechem, famously declaring, 'as for me and my household, we will serve the LORD.'"),
 ],
 "themes":["Misunderstandings within God's community can be resolved through honest communication rather than assumption.","A life well-lived can end by calling others to renewed, decisive commitment."],
 "expositor":("davis","Dale Ralph Davis noted that Joshua's famous declaration was not a private sentiment but a public challenge, modeling how a leader's own resolved commitment can call an entire community to decision."),
 "reflect":"Like Joshua's household declaration, what would it look like for you to make your own commitment to God more publicly clear to those around you?"},

{"day":44,"book":"Judges","ref":"Judges 1-5","title":"The Cycle Begins",
 "chapters":[
  ("Judg 1","After Joshua's death, Israel's tribes fail to fully drive out the remaining Canaanites, setting up the book's recurring problem."),
  ("Judg 2","An angel rebukes Israel for compromise, and the book's tragic cycle is introduced: apostasy, oppression, crying out, and deliverance through a judge."),
  ("Judg 3","The first judges -- Othniel, Ehud, and Shamgar -- deliver Israel from foreign oppression through unconventional means."),
  ("Judg 4","Deborah, a prophetess and judge, and Barak lead Israel to victory over Canaanite forces, with Jael delivering the final blow to the enemy commander."),
  ("Judg 5","The Song of Deborah celebrates the victory in poetic form, honoring both God's deliverance and Jael's decisive action."),
 ],
 "themes":["Partial obedience to God's instructions creates long-term vulnerabilities.","God can use unexpected people to accomplish decisive deliverance."],
 "expositor":("davis","Dale Ralph Davis observed that Judges' recurring cycle -- apostasy, oppression, crying out, deliverance -- reveals a God who remains stubbornly gracious toward His people even as they repeatedly abandon Him."),
 "reflect":"Do you recognize any version of that same cycle -- drifting, consequences, crying out, restoration -- in your own spiritual life?"},

{"day":45,"book":"Judges","ref":"Judges 6-10","title":"Gideon's Reluctant Faith",
 "chapters":[
  ("Judg 6","Gideon, hiding from Midianite oppressors, is called by God despite his self-doubt and initial demands for confirming signs."),
  ("Judg 7","God deliberately reduces Gideon's army to just 300 men so the ensuing victory would be credited to Him alone."),
  ("Judg 8","Gideon's victory over Midian is followed by his tragic creation of an idolatrous ephod that becomes a snare to Israel."),
  ("Judg 9","Gideon's son Abimelech ruthlessly seizes power through violence, ruling briefly and disastrously before meeting a humiliating end."),
  ("Judg 10","Israel again falls into idolatry, and after crying out under Ammonite oppression, God raises up Jephthah as the next judge."),
 ],
 "themes":["God sometimes reduces our resources specifically so His power, not ours, gets the credit.","Victory in one area doesn't guarantee protection from creating new spiritual snares afterward."],
 "expositor":("mcgee","McGee taught that God's reduction of Gideon's army to 300 wasn't about efficiency but about ensuring Israel couldn't 'boast that her own strength has saved her' -- a principle just as relevant to any success we're tempted to credit to ourselves."),
 "reflect":"Is there a recent success where you've quietly credited your own strength rather than God's provision?"},

{"day":46,"book":"Judges","ref":"Judges 11-15","title":"Rash Vows, Compromised Strength",
 "chapters":[
  ("Judg 11","Jephthah defeats the Ammonites but makes a tragic, rash vow that costs his own daughter dearly."),
  ("Judg 12","Internal conflict erupts between Jephthah's forces and the tribe of Ephraim, revealing growing disunity among Israel's tribes."),
  ("Judg 13","Samson's birth is announced to his previously barren parents by the angel of the LORD, with his Nazirite calling specified from before birth."),
  ("Judg 14","Samson's ill-advised marriage to a Philistine woman leads to a riddle contest, betrayal, and violent retaliation."),
  ("Judg 15","Samson's cycle of personal vengeance against the Philistines escalates, though God's Spirit still empowers his remarkable feats of strength."),
 ],
 "themes":["Rash vows and impulsive decisions can carry devastating, unintended consequences.","God's Spirit can empower someone even amid a deeply flawed, compromised character."],
 "expositor":("kaiser","Kaiser noted that Samson's story is deliberately unsettling -- a man empowered by God's Spirit for remarkable feats, yet consistently governed by impulsive personal desire rather than covenant faithfulness, showing that gifting and character are not the same thing."),
 "reflect":"Is there an area where you've assumed being gifted or capable in something meant your character in that area was also healthy?"},

{"day":47,"book":"Judges","ref":"Judges 16-18","title":"Samson's Fall, Israel's Confusion",
 "chapters":[
  ("Judg 16","Samson's fatal weakness for Delilah leads to his betrayal, capture, and blinding, though his final act of strength brings down the Philistine temple with him."),
  ("Judg 17","A man named Micah sets up his own private idols and shrine, illustrating the book's closing theme of religious chaos without central authority."),
  ("Judg 18","The tribe of Dan violently seizes territory and steals Micah's idols, establishing their own corrupt, unauthorized worship site."),
 ],
 "themes":["Persistent compromise with temptation eventually leads to devastating loss.","Religious activity without genuine covenant faithfulness produces confusion, not blessing."],
 "expositor":("davis","Dale Ralph Davis pointed out that Samson's tragic pattern with Delilah shows how repeated, small compromises with a known weakness eventually cost him everything he had been given to steward."),
 "reflect":"Is there a known weakness you keep flirting with rather than decisively avoiding, the way Samson kept returning to Delilah?"},

{"day":48,"book":"Judges","ref":"Judges 19-21","title":"Everyone Did as They Saw Fit",
 "chapters":[
  ("Judg 19","A horrifying account of a Levite's concubine's assault and murder in Gibeah reveals the depths of Israel's moral collapse."),
  ("Judg 20","Civil war erupts between the tribe of Benjamin and the rest of Israel in response to the Gibeah atrocity."),
  ("Judg 21","The book closes with the sobering refrain, 'In those days Israel had no king; everyone did as they saw fit' -- summarizing the entire era's tragic chaos."),
 ],
 "themes":["A society without shared moral accountability descends quickly into chaos and violence.","The book's tragic ending implicitly builds a case for the need for godly, centralized leadership."],
 "expositor":("kaiser","Kaiser observed that Judges' closing refrain functions as the book's thesis statement, diagnosing the root problem behind every preceding tragedy: the absence of submission to God's rightful rule, not merely the absence of a human king."),
 "reflect":"Where in your own life might 'doing what seems right in your own eyes' be quietly substituting for submitting to God's actual authority?"},

{"day":49,"book":"Ruth","ref":"Ruth 1-4","title":"Loyalty, Redemption, and a Royal Line",
 "chapters":[
  ("Ruth 1","Naomi, widowed and bereft of her sons in Moab, returns to Bethlehem, and her Moabite daughter-in-law Ruth loyally commits to stay with her."),
  ("Ruth 2","Ruth gleans in the fields of Boaz, a relative of Naomi's late husband, who shows her unusual kindness and protection."),
  ("Ruth 3","Naomi instructs Ruth to appeal to Boaz as a potential 'kinsman-redeemer' to secure their family's future."),
  ("Ruth 4","Boaz legally redeems Naomi's family line by marrying Ruth, and their resulting son Obed becomes the grandfather of King David."),
 ],
 "themes":["God's providence works quietly through ordinary faithfulness and loyalty, not dramatic miracles.","The kinsman-redeemer role pictures the far greater redemption Christ would later accomplish."],
 "expositor":("kidner","Kidner noted that Boaz's role as kinsman-redeemer -- someone with both the right and the willingness to rescue Naomi and Ruth's family -- anticipates the New Testament's picture of Christ as the one uniquely qualified and willing to redeem His people."),
 "reflect":"Where in your own story might God's providence be working quietly, through ordinary faithfulness rather than dramatic intervention?"},

{"day":50,"book":"1 Samuel","ref":"1 Samuel 1-5","title":"A Prayer Answered, an Ark Uncontrollable",
 "chapters":[
  ("1 Sam 1","Hannah, in deep anguish over her barrenness, prays fervently and vows her future son to the LORD's service; Samuel is born in answer to her prayer."),
  ("1 Sam 2","Hannah's prayer of praise celebrates God's reversal of the proud and humble, while Eli's corrupt sons abuse their priestly position."),
  ("1 Sam 3","The boy Samuel receives his first prophetic call from the LORD in the night, launching his lifelong prophetic ministry."),
  ("1 Sam 4","Israel's superstitious use of the Ark as a good-luck charm in battle fails catastrophically, and the Ark is captured by the Philistines."),
  ("1 Sam 5","The captured Ark wreaks havoc among the Philistines, toppling their god Dagon and afflicting their cities, proving God needs no human protection."),
 ],
 "themes":["Fervent, honest prayer in anguish can be the very means God uses to answer.","God's holiness needs no human protection or superstitious manipulation."],
 "expositor":("wiersbe","Wiersbe noted that Hannah's prayer models how honest anguish poured out before God, rather than suppressed or hidden, can become the very occasion for both personal transformation and answered prayer."),
 "reflect":"Is there a deep longing you've been reluctant to pour out honestly before God the way Hannah did?"},

{"day":51,"book":"1 Samuel","ref":"1 Samuel 6-10","title":"A King Like the Nations",
 "chapters":[
  ("1 Sam 6","The Philistines, desperate to be rid of the Ark's disruptive presence, send it back to Israel with guilt offerings."),
  ("1 Sam 7","Samuel calls Israel to repentance and decisive victory follows, memorialized with the 'Ebenezer' stone -- 'thus far the LORD has helped us.'"),
  ("1 Sam 8","Israel demands a king 'such as all the other nations have,' rejecting God's direct kingship despite Samuel's warnings of a king's costs."),
  ("1 Sam 9","Saul, a tall and impressive young man, is providentially led to Samuel while searching for his father's lost donkeys."),
  ("1 Sam 10","Samuel anoints Saul as Israel's first king, and Saul is confirmed publicly by lot before the assembled nation."),
 ],
 "themes":["Memorializing God's help strengthens future faith.","Rejecting God's direct rule in favor of human structures carries real, if permitted, costs."],
 "expositor":("mcgee","McGee observed that Israel's demand for a king in 1 Samuel 8 wasn't primarily about government structure but about rejecting God's direct kingship over them -- a pattern of wanting to be like the surrounding culture rather than distinctly Godward."),
 "reflect":"Is there an area where you've wanted to conform to surrounding culture rather than trust God's often-different way of doing things?"},

{"day":52,"book":"1 Samuel","ref":"1 Samuel 11-15","title":"A Promising Start, A Costly Compromise",
 "chapters":[
  ("1 Sam 11","Saul's decisive military rescue of Jabesh-Gilead confirms his kingship to a still-skeptical nation."),
  ("1 Sam 12","Samuel's farewell address reaffirms God's faithfulness while warning Israel and their new king to remain faithful to the covenant."),
  ("1 Sam 13","Saul's impatient, unauthorized offering of sacrifice reveals a troubling disregard for God's specific instructions."),
  ("1 Sam 14","Saul's son Jonathan's bold faith secures a remarkable victory over the Philistines, contrasted with Saul's rash, harmful vow."),
  ("1 Sam 15","Saul's incomplete obedience regarding the Amalekites -- sparing what God commanded destroyed -- results in God rejecting him as king."),
 ],
 "themes":["Impatience with God's timing can lead to costly, unauthorized shortcuts.","Partial obedience is, in God's eyes, still disobedience."],
 "expositor":("davis","Dale Ralph Davis pointed out that Saul's rejection in 1 Samuel 15 came not from total rebellion but from partial, self-edited obedience -- keeping what seemed reasonable to keep -- showing that half-obedience is functionally still disobedience."),
 "reflect":"Is there an instruction from God you've partially followed, keeping the parts that were convenient?"},

{"day":53,"book":"1 Samuel","ref":"1 Samuel 16-20","title":"The Heart God Sees, The Friendship That Held",
 "chapters":[
  ("1 Sam 16","Samuel anoints young David as Israel's future king, since 'the LORD looks at the heart,' and David begins serving in Saul's court."),
  ("1 Sam 17","David defeats the Philistine giant Goliath with simple faith and a sling, while Saul's army cowers in fear."),
  ("1 Sam 18","David's popularity provokes Saul's murderous jealousy, even as Jonathan's deep loyal friendship with David develops."),
  ("1 Sam 19","Saul's repeated attempts to kill David force David into fleeing for his life, aided by Jonathan and Saul's own daughter Michal."),
  ("1 Sam 20","Jonathan and David renew their covenant of loyal friendship, and Jonathan confirms Saul's murderous intent, forcing David's permanent flight."),
 ],
 "themes":["God evaluates the heart, not outward appearance or credentials.","Loyal friendship can flourish even amid dangerous political tension."],
 "expositor":("wiersbe","Wiersbe noted that Samuel's rejected assumptions about David's older brothers in 1 Samuel 16 -- expecting impressive stature to indicate God's choice -- serve as a corrective for every generation tempted to judge potential by appearance rather than heart."),
 "reflect":"Where might you be assessing someone, including yourself, more by outward impressiveness than by the heart God actually looks at?"},

{"day":54,"book":"1 Samuel","ref":"1 Samuel 21-25","title":"A Fugitive's Restraint",
 "chapters":[
  ("1 Sam 21","David flees to the priest Ahimelech for provisions and to Philistine territory, feigning madness to survive among his enemies."),
  ("1 Sam 22","David gathers a band of followers in the cave of Adullam, while Saul massacres the priests of Nob for aiding David."),
  ("1 Sam 23","David rescues the city of Keilah from the Philistines, then continues evading Saul's relentless pursuit in the wilderness."),
  ("1 Sam 24","David has the opportunity to kill the sleeping Saul in a cave but refuses to harm 'the LORD's anointed,' instead appealing to his conscience."),
  ("1 Sam 25","The wise Abigail intervenes to prevent David's rash revenge against her foolish husband Nabal, later becoming David's wife after Nabal's death."),
 ],
 "themes":["Restraint from personal revenge, even when justified, reflects trust in God's timing and justice.","Wise intervention can prevent rash decisions from causing lasting damage."],
 "expositor":("davis","Dale Ralph Davis observed that David's restraint in sparing Saul's life in the cave models a costly kind of faith -- trusting God to handle justice in His own timing rather than seizing an opportunity for personal vindication."),
 "reflect":"Is there a situation where you're being tempted to take justice into your own hands rather than trust God's timing?"},

{"day":55,"book":"1 Samuel","ref":"1 Samuel 26-28","title":"Consistent Integrity, Desperate Substitutes",
 "chapters":[
  ("1 Sam 26","David again spares Saul's life when given the opportunity, reinforcing his consistent refusal to take vengeance into his own hands."),
  ("1 Sam 27","David, exhausted from Saul's relentless pursuit, takes refuge among the Philistines under King Achish, adopting a risky survival strategy."),
  ("1 Sam 28","Desperate before a decisive battle, Saul consults a medium at Endor in violation of God's law, receiving a dire, final prophecy of doom."),
 ],
 "themes":["Consistent character under repeated pressure demonstrates real, not merely momentary, integrity.","Desperation can tempt even sincere people toward forbidden shortcuts for answers."],
 "expositor":("mcgee","McGee noted that Saul's visit to the medium at Endor shows a man who had spent years ignoring God's actual guidance now desperately seeking any answer, even a forbidden one -- a warning about neglecting ordinary means of hearing God until crisis forces a desperate substitute."),
 "reflect":"Are you cultivating an ongoing relationship with God now, or waiting until a crisis forces you to seek Him urgently?"},

{"day":56,"book":"1 Samuel","ref":"1 Samuel 29-31","title":"Providential Protection, A Tragic End",
 "chapters":[
  ("1 Sam 29","Philistine commanders distrust David's loyalty and send him away before their battle against Israel, providentially sparing him from fighting his own people."),
  ("1 Sam 30","David rescues his family and possessions after an Amalekite raid on Ziklag, showing decisive, faith-filled leadership."),
  ("1 Sam 31","Saul and his sons, including Jonathan, die in battle against the Philistines, tragically ending Israel's first royal dynasty."),
 ],
 "themes":["God's providence can protect us from situations we didn't even realize were dangerous.","Decisive, faith-filled leadership in crisis can restore what seemed lost."],
 "expositor":("davis","Dale Ralph Davis pointed out that the Philistines' distrust of David, which spared him from fighting against Israel, shows God's providence sometimes protects us through circumstances we might otherwise resent, like being excluded or turned away."),
 "reflect":"Is there a closed door or exclusion in your own life that, in hindsight or even now, might actually be God's protective providence?"},

{"day":57,"book":"2 Samuel","ref":"2 Samuel 1-5","title":"Grief, Conflict, and a Unified Throne",
 "chapters":[
  ("2 Sam 1","David mourns Saul and Jonathan's deaths with a genuine, moving lament rather than celebrating his rival's demise."),
  ("2 Sam 2","David is anointed king over Judah, while civil conflict continues with Saul's surviving son Ish-bosheth over the rest of Israel."),
  ("2 Sam 3","Abner's defection to David's side is followed by his treacherous murder by Joab, deeply grieving David."),
  ("2 Sam 4","Ish-bosheth is assassinated, and David swiftly and severely punishes the murderers rather than rewarding them."),
  ("2 Sam 5","David is finally anointed king over all Israel, captures Jerusalem as his capital, and begins to flourish as his reign consolidates."),
 ],
 "themes":["Genuine grief, even for a rival, reflects a heart shaped by grace rather than triumphalism.","God's promises unfold gradually, even through prolonged political conflict."],
 "expositor":("davis","Dale Ralph Davis observed that David's genuine grief over Saul and Jonathan, rather than gloating over a removed rival, reveals a heart already being shaped toward the kind of king God intended him to be."),
 "reflect":"How do you typically respond when someone who has opposed you experiences hardship or downfall?"},

{"day":58,"book":"2 Samuel","ref":"2 Samuel 6-10","title":"The Covenant, and Costly Kindness",
 "chapters":[
  ("2 Sam 6","David brings the Ark to Jerusalem with great celebration, though Uzzah's death for improperly touching it underscores God's continued holiness."),
  ("2 Sam 7","God establishes the Davidic Covenant, promising David an eternal dynasty and throne -- a foundational messianic promise."),
  ("2 Sam 8","David's military victories expand and secure Israel's borders, and he administers justice and righteousness throughout his reign."),
  ("2 Sam 9","David shows covenant loyalty to Jonathan's disabled son Mephibosheth, restoring his inheritance and welcoming him permanently to the king's table."),
  ("2 Sam 10","A diplomatic insult to David's messengers escalates into war with the Ammonites and their Aramean allies."),
 ],
 "themes":["The Davidic Covenant establishes the foundational promise behind all later messianic hope.","Covenant loyalty reflects the character of God's own steadfast love."],
 "expositor":("kaiser","Kaiser has emphasized that the Davidic Covenant in 2 Samuel 7 -- an eternal throne and dynasty -- becomes the central thread the rest of the Old Testament's messianic expectation hangs on, fulfilled ultimately in Christ, the true and eternal Son of David."),
 "reflect":"David extended costly kindness to Mephibosheth, someone who could offer him nothing politically useful in return. Who might God be calling you to extend that kind of loyal kindness to?"},

{"day":59,"book":"2 Samuel","ref":"2 Samuel 11-15","title":"Sin's Compounding Cost",
 "chapters":[
  ("2 Sam 11","David commits adultery with Bathsheba and then arranges her husband Uriah's death to cover up the resulting pregnancy."),
  ("2 Sam 12","The prophet Nathan confronts David with a parable exposing his sin; David repents, though severe consequences still follow within his family."),
  ("2 Sam 13","David's son Amnon rapes his half-sister Tamar, and her brother Absalom's simmering resentment sets up later tragedy."),
  ("2 Sam 14","Absalom is eventually allowed to return from exile, though reconciliation with David remains incomplete and strained."),
  ("2 Sam 15","Absalom orchestrates a calculated rebellion, forcing David to flee Jerusalem in genuine grief and humiliation."),
 ],
 "themes":["Unchecked sin tends to compound -- covering one sin often requires committing worse ones.","Confronting sin honestly, however painful, is the necessary path toward genuine repentance."],
 "expositor":("sproul","Sproul often pointed to Nathan's confrontation of David in 2 Samuel 12 as a model for loving, direct confrontation of sin -- not harsh condemnation, but a clear parable that helped David see his own guilt clearly enough to genuinely repent."),
 "reflect":"Is there a compounding pattern of sin in your own life where the 'cover-up' has become worse than the original failure?"},

{"day":60,"book":"2 Samuel","ref":"2 Samuel 16-20","title":"Humility Under Humiliation",
 "chapters":[
  ("2 Sam 16","David endures public humiliation and cursing during his flight, responding with remarkable humility rather than retaliation."),
  ("2 Sam 17","Absalom rejects wiser counsel in favor of flawed strategy, providentially working in David's favor."),
  ("2 Sam 18","Absalom's rebellion is crushed, and he is killed against David's explicit wishes, plunging the king into deep, conflicted grief."),
  ("2 Sam 19","David is urged to set aside his grief and publicly reaffirm his leadership to reunite a fractured kingdom."),
  ("2 Sam 20","A further rebellion led by Sheba is decisively suppressed, restoring a fragile peace to David's kingdom."),
 ],
 "themes":["Humility under public humiliation can reflect deep trust in God's ultimate vindication.","A fractured community requires intentional, sometimes uncomfortable, leadership to reunite."],
 "expositor":("davis","Dale Ralph Davis noted that David's restrained response to Shimei's cursing -- 'let him curse... it may be that the LORD will look on my affliction' -- shows a king willing to leave vindication to God rather than demanding it immediately for himself."),
 "reflect":"Is there a current unfair critic you're being tempted to retaliate against rather than entrust to God?"},

{"day":61,"book":"2 Samuel","ref":"2 Samuel 21-24","title":"A Lifetime of Songs and Sobering Lessons",
 "chapters":[
  ("2 Sam 21","A famine tied to Saul's earlier broken covenant with the Gibeonites is resolved, and further battles against Philistine giants are recorded."),
  ("2 Sam 22","David's extended song of praise celebrates God as his rock, deliverer, and shield across a lifetime of conflict."),
  ("2 Sam 23","David's 'last words' and a roster of his mightiest warriors honor the loyal men who served faithfully throughout his reign."),
  ("2 Sam 24","David's prideful census provokes God's judgment, resolved through David's purchase of a threshing floor that later becomes the Temple's site."),
 ],
 "themes":["A lifetime of God's faithfulness is worth deliberately recounting and celebrating, not just assuming.","Even great leaders can fall into pride that requires humbling correction."],
 "expositor":("kidner","Kidner observed that David's song of praise in 2 Samuel 22 -- nearly identical to Psalm 18 -- shows a king who, even after decades of both triumph and failure, still instinctively returned to worship as his primary response to reflecting on his life."),
 "reflect":"When you look back over a season of your life, is worship your instinctive response, the way it was for David in his song of praise?"},
]
